The manual two-service example uses sparse labels in reverse registry order. It checks an exact path and a single delivery. Version retirement, clones, file handoff, rollback, retransmission, language combinations and maximum scale are specified in PROTOCOL.md and are outside this small public sanity fixture.
=== sanity.json
{"jobs":[{"services":[{"name":"A","label":10},{"name":"B","label":4}],"limits":{"images":16,"cells":262144,"units":1024,"contexts":32768,"connections":4096,"packets":32768,"files":8192},"events":[{"op":"stage","epoch":1,"policy":"match(A,B) allow;"},{"op":"commit","epoch":1},{"op":"spawn","unit":[0,1,1],"service":"A"},{"op":"spawn","unit":[0,2,1],"service":"B"},{"op":"begin","unit":[0,1,1],"rid":1},{"op":"open","connection":[1,1]},{"op":"send","unit":[0,1,1],"rid":1,"connection":[1,1],"stream":1,"destination":"B"},{"op":"recv","unit":[0,2,1],"rid":1,"connection":[1,1],"stream":1,"wire":null},{"op":"finish","unit":[0,2,1],"rid":1},{"op":"inspect"}]}]}
